using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;using System.Diagnostics;using System.Reflection;using System.Runtime.InteropServices;using Microsoft.Win32.SafeHandles;using System.Web.Script.Serialization;
namespace PZ3D {static class SnapshotCopyStorageTests {
 [DllImport("kernel32.dll",EntryPoint="CreateFileW",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle OpenDirectory(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool DeviceIoControl(SafeFileHandle handle,uint code,byte[] input,uint inputLength,IntPtr output,uint outputLength,out uint returned,IntPtr overlapped);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandleEx(SafeFileHandle handle,int infoClass,out StandardInfo info,uint size);
 [StructLayout(LayoutKind.Sequential)]struct StandardInfo {public long AllocationSize,EndOfFile;public uint NumberOfLinks;public byte DeletePending,Directory;}
 static int checks,failed;static string root;static List<object> results=new List<object>();
 static void Check(bool ok,string label){checks++;if(!ok){failed++;Console.WriteLine("FAIL "+label);}}
 static void Put(string p,string s){Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,s,new UTF8Encoding(false));}
 static void Native(FileStream file,uint code,byte[] input){uint n;if(!DeviceIoControl(file.SafeFileHandle,code,input,input==null?0:(uint)input.Length,IntPtr.Zero,0,out n,IntPtr.Zero))throw new System.ComponentModel.Win32Exception();}
 static void Sparse(string p,int size,bool nonzero,bool trailingHole){Directory.CreateDirectory(Path.GetDirectoryName(p));using(var f=new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){Native(f,0x900c4,null);f.SetLength(size);if(nonzero){f.Position=65535;f.WriteByte(11);f.WriteByte(12);f.Position=131071;f.WriteByte(13);f.WriteByte(14);f.Position=1048575;f.WriteByte(21);f.WriteByte(22);if(!trailingHole){f.Position=size-1;f.WriteByte(15);}}f.Flush(true);}}
 static void Compressed(string p,bool nonzero=false){Directory.CreateDirectory(Path.GetDirectoryName(p));using(var f=new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){Native(f,0x9c040,new byte[]{1,0});byte[] zero=new byte[65536];if(nonzero)for(int i=0;i<zero.Length;i++)zero[i]=65;for(int i=0;i<128;i++)f.Write(zero,0,zero.Length);f.Flush(true);}}
 sealed class Item {public string Path,Hash;public long Length,Write,Allocated;public FileAttributes Attributes;}
 static List<Item> Measure(string path){var rows=new List<Item>();if(!Directory.Exists(path))return rows;foreach(string p in Directory.GetFiles(path,"*",SearchOption.AllDirectories)){var f=new FileInfo(p);StandardInfo info;using(var file=File.OpenRead(p)){if(!GetFileInformationByHandleEx(file.SafeFileHandle,1,out info,(uint)Marshal.SizeOf(typeof(StandardInfo))))throw new System.ComponentModel.Win32Exception();}rows.Add(new Item{Path=p.Substring(path.Length+1),Hash=DlssInstaller.HashFile(p),Length=f.Length,Write=f.LastWriteTimeUtc.Ticks,Attributes=f.Attributes,Allocated=info.AllocationSize});}return rows.OrderBy(v=>v.Path,StringComparer.Ordinal).ToList();}
 static bool Unchanged(List<Item>a,List<Item>b){return a.Count==b.Count&&a.Zip(b,(x,y)=>x.Path==y.Path&&x.Hash==y.Hash&&x.Length==y.Length&&x.Write==y.Write&&x.Attributes==y.Attributes&&x.Allocated==y.Allocated).All(v=>v);}
 static void SnapshotCopy(string source,string target,CancellationToken token,Action<long,string> progress){var files=Directory.GetFiles(source,"*",SearchOption.AllDirectories).Select(p=>new SaveEnvironmentFile{Path=p.Substring(source.Length+1).Replace('\\','/'),Bytes=new FileInfo(p).Length,WriteTicks=File.GetLastWriteTimeUtc(p).Ticks}).ToArray();try{typeof(SaveEnvironments).GetMethod("Copy",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{source,target,files,token,progress,null});}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Copy(string kind,string source,string target,CancellationToken token,Action<long,string> progress){if(kind=="snapshot")SnapshotCopy(source,target,token,progress);else{var library=new VersionLibrary(Path.Combine(Path.GetDirectoryName(source),"数据"),source,Path.Combine(Path.GetDirectoryName(source),"玩家"));library.Preserve(source,target,"测试版本",token,p=>{if(p.Stage=="copy"&&progress!=null)progress(p.BytesCopied,p.File);});}}
 static string Source(string folder){string p=Path.Combine(folder,"中文来源");Put(Path.Combine(p,"ProjectZomboid64.exe"),"owned, never execute");Put(Path.Combine(p,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(p,"version.txt"),"42.21.0");return p;}
 static void Storage(string kind){string r=Path.Combine(root,kind+"-storage"),source=Source(r),target=Path.Combine(r,"中文独立副本");Sparse(Path.Combine(source,"media","跨块稀疏.bin"),16*1048576,true,false);Sparse(Path.Combine(source,"media","尾洞稀疏.bin"),4*1048576+19,true,true);Sparse(Path.Combine(source,"media","全零稀疏.bin"),4*1048576,false,true);Sparse(Path.Combine(source,"media","空稀疏.bin"),0,false,true);Compressed(Path.Combine(source,"media","压缩.bin"));Compressed(Path.Combine(source,"media","非零压缩.bin"),true);Put(Path.Combine(source,"media","独立性.txt"),"before source update");File.WriteAllBytes(Path.Combine(source,"media","普通空文件"),new byte[0]);foreach(string p in Directory.GetFiles(source,"*",SearchOption.AllDirectories))File.SetLastWriteTimeUtc(p,new DateTime(2020,2,3,4,5,6,DateTimeKind.Utc));var before=Measure(source);Copy(kind,source,target,CancellationToken.None,null);var after=Measure(source);var copied=Measure(target);Check(Unchanged(before,after),kind+" sources unchanged including allocation");Check(before.Count==copied.Count,kind+" exact file count");foreach(var item in before){var output=copied.Single(v=>v.Path==item.Path);Check(output.Hash==item.Hash&&output.Length==item.Length,kind+" bytes "+item.Path);Check(output.Write==item.Write,kind+" destination timestamp "+item.Path);if((item.Attributes&(FileAttributes.SparseFile|FileAttributes.Compressed))!=0){Check((output.Attributes&(FileAttributes.SparseFile|FileAttributes.Compressed))==(item.Attributes&(FileAttributes.SparseFile|FileAttributes.Compressed)),kind+" storage flags "+item.Path);Check(output.Allocated<=Math.Max(65536,item.Allocated*3),kind+" allocation bound "+item.Path+" "+item.Allocated+" -> "+output.Allocated);}}string independent=Path.Combine(target,"media","独立性.txt"),frozenHash=DlssInstaller.HashFile(independent);Put(Path.Combine(source,"media","独立性.txt"),"owned source changed after copy");Check(DlssInstaller.HashFile(independent)==frozenHash,kind+" output survives source edit");results.Add(new{Kind=kind,Source=source,Target=target,Before=before,After=after,Copied=copied,IndependentAfterSourceEdit=true});}
 static void CompressedParent(string kind){string r=Path.Combine(root,kind+"-compressed-parent"),source=Source(r),parent=Path.Combine(r,"压缩父目录"),target=Path.Combine(parent,"独立副本");Sparse(Path.Combine(source,"稀疏资源.bin"),4*1048576+19,true,true);Directory.CreateDirectory(parent);using(var handle=OpenDirectory(parent,0xC0000000,7,IntPtr.Zero,3,0x02000000,IntPtr.Zero)){if(handle.IsInvalid)throw new System.ComponentModel.Win32Exception();uint n;if(!DeviceIoControl(handle,0x9c040,new byte[]{1,0},2,IntPtr.Zero,0,out n,IntPtr.Zero))throw new System.ComponentModel.Win32Exception();}var before=Measure(source);bool complete=false;string error=null;try{Copy(kind,source,target,CancellationToken.None,null);complete=true;}catch(IOException e){error=e.ToString();}Check(complete,kind+" sparse copy into compressed parent: "+error);if(complete){var copied=Measure(target);var original=before.Single(v=>v.Path=="稀疏资源.bin");var output=copied.Single(v=>v.Path=="稀疏资源.bin");Check(output.Hash==original.Hash&&output.Length==original.Length,kind+" compressed-parent bytes");Check((output.Attributes&FileAttributes.SparseFile)!=0&&output.Allocated<=Math.Max(65536,original.Allocated*3),kind+" compressed-parent sparse allocation");}Check(Unchanged(before,Measure(source)),kind+" compressed-parent source unchanged");}
 static void Tiny(string kind){string r=Path.Combine(root,kind+"-tiny"),source=Source(r),target=Path.Combine(r,"独立副本");for(int i=0;i<128;i++)Put(Path.Combine(source,"media","中文-"+i+".txt"),new string('x',4096));GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();int gen2=GC.CollectionCount(2);long allocatedBefore=AppDomain.CurrentDomain.MonitoringTotalAllocatedMemorySize;var clock=Stopwatch.StartNew();Copy(kind,source,target,CancellationToken.None,null);double ms=clock.Elapsed.TotalMilliseconds;int delta=GC.CollectionCount(2)-gen2;long allocated=AppDomain.CurrentDomain.MonitoringTotalAllocatedMemorySize-allocatedBefore;Check(allocated<=32L*1048576,kind+" small-file managed allocation <=32MiB, actual "+allocated);Check(Directory.GetFiles(target,"*",SearchOption.AllDirectories).Length==131,kind+" tiny file count");results.Add(new{Kind=kind,TinyFiles=131,Milliseconds=ms,FullGCs=delta,ManagedAllocatedBytes=allocated});}
 static void Cancellation(string kind){string r=Path.Combine(root,kind+"-cancel"),source=Source(r),target=Path.Combine(r,"取消副本"),retry=Path.Combine(r,"重试副本");using(var f=new FileStream(Path.Combine(source,"large.bin"),FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] data=new byte[1048576];new Random(11).NextBytes(data);for(int i=0;i<8;i++)f.Write(data,0,data.Length);}var before=Measure(source);bool canceled=false;long observed=0;using(var token=new CancellationTokenSource()){try{Copy(kind,source,target,token.Token,(n,p)=>{if(p!=null&&p.EndsWith("large.bin",StringComparison.OrdinalIgnoreCase)&&n>0){bool writeDenied=false;try{using(var writer=new FileStream(Path.Combine(source,"large.bin"),FileMode.Open,FileAccess.Write,FileShare.ReadWrite)){} }catch(IOException){writeDenied=true;}Check(writeDenied,kind+" read sharing rejects writes during actual copy");observed=n;token.Cancel();}});}catch(OperationCanceledException){canceled=true;}}Check(canceled&&observed>0&&observed<8*1048576,kind+" cancellation inside real large-file copy");Check(Unchanged(before,Measure(source)),kind+" cancel source unchanged");if(kind=="version")Check(!Directory.Exists(target)&&!Directory.GetDirectories(r,"*.partial-*").Any(),kind+" cancelled staging cleaned");Copy(kind,source,retry,CancellationToken.None,null);Check(Unchanged(before,Measure(source)),kind+" retry source unchanged");Check(before.Select(v=>v.Hash).SequenceEqual(Measure(retry).Select(v=>v.Hash)),kind+" retry actual bytes");}
 static void ChangedSource(){string r=Path.Combine(root,"version-source-change"),source=Source(r),target=Path.Combine(r,"应拒绝副本");bool changed=false,rejected=false;var before=Measure(source);var library=new VersionLibrary(Path.Combine(r,"数据"),source,Path.Combine(r,"玩家"));try{library.Preserve(source,target,"改动",CancellationToken.None,p=>{if(p.Stage=="copy"&&!changed){changed=true;Put(Path.Combine(source,"来源变化.txt"),"source deliberately changed during copy");}});}catch(IOException){rejected=true;}Check(rejected&&!Directory.Exists(target)&&!Directory.GetDirectories(r,"*.partial-*").Any(),"changed source rejects/cleans actual version copy");Check(before.All(i=>Measure(source).Any(a=>a.Path==i.Path&&a.Hash==i.Hash)),"changed-source test never modifies original files");}
 public static int Main(string[] args){try{AppDomain.MonitoringIsEnabled=true;root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);foreach(string kind in new[]{"version","snapshot"}){Storage(kind);CompressedParent(kind);Tiny(kind);Cancellation(kind);}ChangedSource();File.WriteAllText(Path.Combine(root,"regression-results.json"),new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(new{Checks=checks,Failed=failed,Results=results,Scope="Actual compiled production Preserve and snapshot Copy on isolated files, no desktop/game launch. Snapshot Copy primitive does not own tree cleanup; full Create cleanup is verified separately."}),new UTF8Encoding(false));Console.WriteLine((failed==0?"PASS":"FAIL")+" "+checks+" checks, "+failed+" failed");return failed==0?0:1;}catch(Exception e){Console.WriteLine(e);return 2;}}
